item.command:
/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { lineFromRequest } from './src/api.js';

let errorMessage;
try {
  lineFromRequest({ sku: 'A', quantity: '' });
} catch (error) {
  assert.equal(error.constructor, Error);
  errorMessage = error.message;
}

const answer = {
  changed_file: 'src/quantity.js',
  zero_result: lineFromRequest({ sku: ' A ', quantity: '0' }),
  error_message: errorMessage,
};
assert.deepEqual(answer, {
  changed_file: 'src/quantity.js',
  zero_result: { sku: 'A', quantity: 0, active: false },
  error_message: 'invalid quantity',
});
writeFileSync('answer.json', "'`${JSON.stringify(answer, null, 2)}'"\\n"'`);
assert.deepEqual(JSON.parse(readFileSync('"'answer.json', 'utf8')), answer);
console.log(JSON.stringify(answer));
NODE"

